22	public class ChatController extends BasePlayerController {
23	    private static final String TAG = ChatController.class.getSimpleName();
24	    /**
25	     * NOTE: Don't remove duplicates! They contain different chars.
26	     */
27	    private static final String[] BLACK_LIST = {". XYZ", ". ХYZ", "⠄XYZ", "⠄ХYZ", "Ricardo Merlino", "⠄СОM", ".COM", ".СОM", ". COM"};
28	    private LiveChatService mChatService;
29	    private Disposable mChatAction;
30	    private String mLiveChatKey;
31	
32	    @Override
33	    public void onInit() {
34	        mChatService = YouTubeServiceManager.instance().getLiveChatService();
35	    }
36	
37	    @Override
38	    public void onMetadata(MediaItemMetadata metadata) {
39	        if (getPlayer() == null) {
40	            return;
41	        }
42	
43	        mLiveChatKey = metadata != null ? metadata.getLiveChatKey() : null;
44	
45	        if (mLiveChatKey != null) {
46	            getPlayer().setButtonState(R.id.action_chat, getPlayerData().isLiveChatEnabled() ? PlayerUI.BUTTON_ON : PlayerUI.BUTTON_OFF);
47	        }
48	
49	        if (getPlayerData().isLiveChatEnabled()) {
50	            openLiveChat();
51	        }
52	    }
53	
54	    private void openLiveChat() {
55	        disposeActions();
56	
57	        if (mLiveChatKey == null || getPlayer() == null) {
58	            return;
59	        }
60	
61	        ChatReceiver chatReceiver = new ChatReceiverImpl();
62	        getPlayer().setChatReceiver(chatReceiver);
63	
64	        mChatAction = mChatService.openLiveChatObserve(mLiveChatKey)
65	                .subscribe(
66	                        chatItem -> {
67	                            Log.d(TAG, chatItem.getMessage());
68	                            if (checkItem(chatItem)) {
69	                                chatReceiver.addChatItem(chatItem);
70	                            }
71	                        },
72	                        error -> {
73	                            Log.e(TAG, error.getMessage());
74	                            error.printStackTrace();
75	                        },
76	                        () -> Log.e(TAG, "Live chat session has been closed")
77	                );
78	    }
79	
80	    @Override
81	    public void onButtonClicked(int buttonId, int buttonState) {
82	        if (buttonId == R.id.action_chat) {
83	            if (mLiveChatKey != null) {
84	                enableLiveChat(buttonState != PlayerUI.BUTTON_ON);
85	            }
86	        }
87	    }
88	
89	    @Override
90	    public void onButtonLongClicked(int buttonId, int buttonState) {
91	        if (buttonId == R.id.action_chat) {
92	            String chatCategoryTitle = getContext().getString(R.string.open_chat);
93	
94	            AppDialogPresenter settingsPresenter = AppDialogPresenter.instance(getContext());
95	
96	            List<OptionItem> options = new ArrayList<>();
97	
98	            options.add(UiOptionItem.from(getContext().getString(R.string.option_disabled),
99	                    optionItem -> {
100	                        enableLiveChat(false);
101	                        settingsPresenter.closeDialog();
102	                    },
103	                    !getPlayerData().isLiveChatEnabled()));
104	
105	            options.add(UiOptionItem.from(getContext().getString(R.string.chat_left),
106	                    optionItem -> {
107	                        placeChatLeft(true);
108	                        enableLiveChat(true);
109	                        settingsPresenter.closeDialog();
110	                    },
111	                    getPlayerData().isLiveChatEnabled() && isChatPlacedLeft()));
112	
113	            options.add(UiOptionItem.from(getContext().getString(R.string.chat_right),
114	                    optionItem -> {
115	                        placeChatLeft(false);
116	                        enableLiveChat(true);
117	                        settingsPresenter.closeDialog();
118	                    },
119	                    getPlayerData().isLiveChatEnabled() && !isChatPlacedLeft()));
120	
121	            settingsPresenter.appendRadioCategory(chatCategoryTitle, options);
122	
123	            settingsPresenter.showDialog(chatCategoryTitle);
124	        }
125	    }
126	
127	    @Override
128	    public void onEngineReleased() {
129	        disposeActions();
130	    }
131	
132	    @Override
133	    public void onFinish() {
134	        disposeActions();
135	    }
136	
137	    private void disposeActions() {
138	        if (RxHelper.isAnyActionRunning(mChatAction)) {
139	            RxHelper.disposeActions(mChatAction);
140	            getPlayer().setChatReceiver(null);
141	        }
142	    }
143	
144	    private boolean checkItem(ChatItem chatItem) {
145	        if (chatItem == null || chatItem.getAuthorName() == null) {
146	            return false;
147	        }
148	
149	        String authorName = chatItem.getAuthorName();
150	
151	        for (String spammer : BLACK_LIST) {
152	            if (authorName.toLowerCase().contains(spammer.toLowerCase())) {
153	                return false;
154	            }
155	        }
156	
157	        return true;
158	    }
159	
160	    private void enableLiveChat(boolean enabled) {
161	        if (enabled) {
162	            openLiveChat();
163	        } else {
164	            disposeActions();
165	        }
166	        getPlayerData().setLiveChatEnabled(enabled);
167	
168	        if (mLiveChatKey != null) {
169	            getPlayer().setButtonState(R.id.action_chat, enabled ? PlayerUI.BUTTON_ON : PlayerUI.BUTTON_OFF);
170	        }
171	    }
172	
173	    private void placeChatLeft(boolean left) {
174	        if (mLiveChatKey != null) {
175	            getPlayerTweaksData().setChatPlacedLeft(left);
176	        } else {
177	            getPlayerTweaksData().setCommentsPlacedLeft(left);
178	        }
179	    }
180	
181	    private boolean isChatPlacedLeft() {
182	        return mLiveChatKey != null ? getPlayerTweaksData().isChatPlacedLeft() : getPlayerTweaksData().isCommentsPlacedLeft();
183	    }
184	}
