178	    private void toggleLike(CommentsReceiver receiver, CommentItem commentItem) {
179	        MyCommentItem myCommentItem = MyCommentItem.from(commentItem);
180	        myCommentItem.setLiked(!myCommentItem.isLiked());
181	
182	        receiver.sync(myCommentItem);
183	
184	        RxHelper.execute(
185	                getCommentsService().toggleLikeObserve(commentItem.getNestedCommentsKey()), e -> MessageHelpers.showMessage(getContext(), e.getMessage()));
186	    }
