200	        private MyCommentItem(
201	                String id, String message, String authorName, String authorPhoto, String publishedDate,
202	                String nestedCommentsKey, boolean isLiked, String likeCount, String replyCount, boolean isEmpty) {
203	            mId = id;
204	            mMessage = message;
205	            mAuthorName = authorName;
206	            mAuthorPhoto = authorPhoto;
207	            mPublishedDate = publishedDate;
208	            mNestedCommentsKey = nestedCommentsKey;
209	            mIsLiked = isLiked;
210	            mLikeCount = likeCount;
211	            mReplyCount = replyCount;
212	            mIsEmpty = isEmpty;
213	        }
