215	        @Override
216	        public String getId() {
217	            return mId;
218	        }
219	
220	        @Override
221	        public String getMessage() {
222	            return mMessage;
223	        }
224	
225	        @Override
226	        public String getAuthorName() {
227	            return mAuthorName;
228	        }
229	
230	        @Override
231	        public String getAuthorPhoto() {
232	            return mAuthorPhoto;
233	        }
234	
235	        @Override
236	        public String getPublishedDate() {
237	            return mPublishedDate;
238	        }
239	
240	        @Override
241	        public String getNestedCommentsKey() {
242	            return mNestedCommentsKey;
243	        }
244	
245	        @Override
246	        public boolean isLiked() {
247	            return mIsLiked;
248	        }
249	
250	        public void setLiked(boolean isLiked) {
251	            if (mIsLiked == isLiked) {
252	                return;
253	            }
254	
255	            mIsLiked = isLiked;
256	
257	            if (mLikeCount == null) {
258	                mLikeCount = String.valueOf(0);
259	            }
260	
261	            if (Helpers.isInteger(getLikeCount())) {
262	                int likeCount = Helpers.parseInt(getLikeCount());
263	                int count = isLiked ? ++likeCount : --likeCount;
264	                mLikeCount = count > 0 ? String.valueOf(count) : null;
265	            }
266	        }
267	
268	        @Override
269	        public String getLikeCount() {
270	            return mLikeCount;
271	        }
272	
273	        @Override
274	        public String getReplyCount() {
275	            return mReplyCount;
276	        }
277	
278	        @Override
279	        public boolean isEmpty() {
280	            return mIsEmpty;
281	        }
282	
283	        public static MyCommentItem from(CommentItem commentItem) {
284	            return new MyCommentItem(commentItem.getId(), commentItem.getMessage(), commentItem.getAuthorName(),
285	                    commentItem.getAuthorPhoto(), commentItem.getPublishedDate(), commentItem.getNestedCommentsKey(),
286	                    commentItem.isLiked(), commentItem.getLikeCount(), commentItem.getReplyCount(), commentItem.isEmpty());
287	        }
288	    }
