340	
341	        int prevSize = sizeTimestamp != null ? sizeTimestamp.first : 0;
342	        int newSize = Math.max(group.getSize(), 0);
343	        int totalSize = prevSize + newSize;
344	
345	        MainUIData mainUIData = MainUIData.instance(context);
346	
347	        boolean isScaledUIEnabled = mainUIData.getUIScale() < 0.8f || mainUIData.getVideoGridScale() < 0.8f;
348	        int minScaledSize = isGrid ? MIN_SCALED_GRID_GROUP_SIZE : MIN_SCALED_ROW_GROUP_SIZE;
349	        int minSize = isGrid ? MIN_GRID_GROUP_SIZE : MIN_ROW_GROUP_SIZE;
350	        boolean groupTooSmall = isScaledUIEnabled ? totalSize < minScaledSize : totalSize < minSize;
351	
